import{_ as i,o as l,c as o,a4 as a}from"./chunks/framework.vNSRaLQv.js";const m=JSON.parse('{"title":"HomeSense Studio v2 近期交接文档","description":"","frontmatter":{"title":"HomeSense Studio v2 近期交接文档","date":"2026-06-18T00:00:00.000Z"},"headers":[],"relativePath":"posts/HomeSense近期交接文档.md","filePath":"posts/HomeSense近期交接文档.md"}'),t={name:"posts/HomeSense近期交接文档.md"};function r(d,e,n,s,c,u){return l(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="homesense-studio-v2-近期交接文档" tabindex="-1">HomeSense Studio v2 近期交接文档 <a class="header-anchor" href="#homesense-studio-v2-近期交接文档" aria-label="Permalink to &quot;HomeSense Studio v2 近期交接文档&quot;">​</a></h1><p>日期：2026-06-18<br> 项目路径：<code>D:\\files\\HomeSense-Studio-v2</code></p><h2 id="_1-当前背景" tabindex="-1">1. 当前背景 <a class="header-anchor" href="#_1-当前背景" aria-label="Permalink to &quot;1. 当前背景&quot;">​</a></h2><p>HomeSense Studio v2 近期主线已经从“泛化大架构讨论”收回到更具体的设备与系统能力层：</p><ul><li>认证中心负责真实连接来源：MI、ADB、SSH/SFTP、AList、Sunshine/Moonlight 等。</li><li>设备管理负责组合这些来源，不直接承担协议注册中心职责。</li><li>终端保留给人类使用，Agent 未来优先使用封装能力，而不是直接操控 shell。</li><li>文件、终端、串流都倾向做成单独 session 页面，而不是挤在设备详情页底部。</li><li>HomeSense 作为主体，外部项目只作为参考或 runtime/driver 内核，不让外部系统反客为主。</li></ul><p>当前工作区有较多未提交改动，重点集中在：</p><ul><li>ADB 串流 / 文件页面</li><li>SSH/SFTP 文件入口</li><li>统一存储层</li><li>Sunshine/Moonlight 串流入口</li><li>启动脚本</li><li><code>packages/moonlight-driver</code> 轻量占位 driver</li></ul><h2 id="_2-近期已完成或接近完成的内容" tabindex="-1">2. 近期已完成或接近完成的内容 <a class="header-anchor" href="#_2-近期已完成或接近完成的内容" aria-label="Permalink to &quot;2. 近期已完成或接近完成的内容&quot;">​</a></h2><h3 id="_2-1-adb" tabindex="-1">2.1 ADB <a class="header-anchor" href="#_2-1-adb" aria-label="Permalink to &quot;2.1 ADB&quot;">​</a></h3><p>ADB 方向已经形成三个主要入口：</p><ul><li>控制台：ADB shell，独立 session 页面。</li><li>串流：基于 scrcpy bridge，独立页面 <code>AdbStreamSessionView.vue</code>。</li><li>文件系统：新增 <code>AdbFilesSessionView.vue</code>，默认应围绕 <code>/sdcard/</code> 展示。</li></ul><p>近期修过的问题：</p><ul><li>scrcpy 串流坐标映射。</li><li>鼠标拖拽。</li><li>串流页从工作台拆成单独 session。</li><li>ADB 文件路径重复 <code>/sdcard//sdcard</code> 的问题方向已明确，需要继续检查路径 join。</li></ul><h3 id="_2-2-ssh-sftp" tabindex="-1">2.2 SSH / SFTP <a class="header-anchor" href="#_2-2-ssh-sftp" aria-label="Permalink to &quot;2.2 SSH / SFTP&quot;">​</a></h3><p>方向已经定为：SSH 和 SFTP 共用同一套认证来源，在认证中心显示为 <code>SSH/SFTP</code>。</p><p>相关改动：</p><ul><li><code>terminal/target-resolver.ts</code> 支持从 <code>ssh_target_id</code> / <code>ssh_authorization_id</code> 解析。</li><li><code>storage</code> 增加设备文件入口。</li><li>新增 <code>DeviceFilesSessionView.vue</code>，用于 SSH/SFTP 设备文件操作。</li></ul><p>待继续验证：</p><ul><li>SSH 控制台是否还能稳定打开。</li><li>SFTP 文件入口是否能绑定到同一 SSH/SFTP 认证。</li><li>不要补兜底掩盖问题，要查为什么 target/credential 缺失。</li></ul><h3 id="_2-3-统一文件系统" tabindex="-1">2.3 统一文件系统 <a class="header-anchor" href="#_2-3-统一文件系统" aria-label="Permalink to &quot;2.3 统一文件系统&quot;">​</a></h3><p>目标是让不同协议进入同一套前端文件管理视图：</p><ul><li>ADB 文件</li><li>SSH/SFTP 文件</li><li>AList / WebDAV / SMB 等后续来源</li></ul><p>已开始做统一存储层：</p><ul><li><code>apps/server/src/storage/*</code></li><li><code>apps/web/src/api/storage.ts</code></li><li><code>StorageCredentialsPanel.vue</code></li></ul><p>近期 TODO：</p><ul><li>继续统一前端文件表格/路径栏/操作按钮。</li><li>跨协议复制是需要做的能力，但不要一次做太大。</li><li>先保证 list / download / upload / mkdir / remove 稳定。</li></ul><h3 id="_2-4-sunshine-moonlight-串流" tabindex="-1">2.4 Sunshine / Moonlight 串流 <a class="header-anchor" href="#_2-4-sunshine-moonlight-串流" aria-label="Permalink to &quot;2.4 Sunshine / Moonlight 串流&quot;">​</a></h3><p>当前状态：</p><ul><li>Sunshine 主机不再作为普通设备新增，而是进入 <code>streaming_hosts</code> 来源表。</li><li>认证中心的 Sunshine/Moonlight 面板已经简化成类似 ADB 的布局： <ul><li>扫描</li><li>候选列表</li><li>保存主机</li><li>主机列表</li><li>探测 / Wake / 串流 / 删除</li></ul></li><li>默认扫描网段固定为 <code>192.168.31.0/24</code>。</li><li>默认扫描端口：<code>47990</code> 和 <code>47989</code>。</li><li><code>47990</code> 使用 <code>https://</code>，能扫到本机 Sunshine：<code>https://192.168.31.204:47990</code>。</li><li>探测已处理 Sunshine 自签 HTTPS 证书问题，<code>401/404</code> 这类 <code>&lt;500</code> 状态视为可达。</li></ul><p>已新增：</p><ul><li><code>StreamingSessionView.vue</code></li><li><code>/sessions/streaming</code></li><li><code>POST /api/streaming-gateway/scan</code></li><li><code>GET /api/streaming-gateway/hosts/:id/session-entry</code></li><li><code>POST /api/streaming-gateway/hosts/:id/pair</code></li></ul><p>注意：</p><ul><li>当前 <code>packages/moonlight-driver</code> 是轻量占位 driver。</li><li>它会生成 PIN、写三份占位 PEM 文件，并标记 <code>mock_pairing: true</code>。</li><li>这不是 Moonlight/Sunshine 的真实证书配对。</li></ul><h2 id="_3-moonlight-当前关键决策" tabindex="-1">3. Moonlight 当前关键决策 <a class="header-anchor" href="#_3-moonlight-当前关键决策" aria-label="Permalink to &quot;3. Moonlight 当前关键决策&quot;">​</a></h2><p>目前讨论出两条路线：</p><h3 id="路线-a-直接接-moonlight-web-stream-release-runtime" tabindex="-1">路线 A：直接接 <code>moonlight-web-stream</code> release/runtime <a class="header-anchor" href="#路线-a-直接接-moonlight-web-stream-release-runtime" aria-label="Permalink to &quot;路线 A：直接接 `moonlight-web-stream` release/runtime&quot;">​</a></h3><p>优点：</p><ul><li>不需要本机编译 Rust。</li><li>最快看到真实串流画面。</li><li>真实配对、WebRTC、键鼠控制都交给现成 runtime。</li></ul><p>缺点：</p><ul><li>配对、用户、主机状态主要在 runtime 内部。</li><li>HomeSense 更像统一入口，而不是完全掌控底层能力。</li></ul><p>当前建议：</p><ul><li>短期优先走这条。</li><li>HomeSense 只保存 runtime URL，例如 <code>MOONLIGHT_WEB_RUNTIME_URL=http://localhost:8080</code>。</li><li>UI 提供“打开 runtime / 去配对 / 去串流”。</li></ul><h3 id="路线-b-内置真实-moonlight-driver" tabindex="-1">路线 B：内置真实 <code>moonlight-driver</code> <a class="header-anchor" href="#路线-b-内置真实-moonlight-driver" aria-label="Permalink to &quot;路线 B：内置真实 `moonlight-driver`&quot;">​</a></h3><p>优点：</p><ul><li>HomeSense 能掌控配对、证书、主机状态、后续 Agent 能力。</li><li>跟 <code>adb-cli / mi-cli / media-cli</code> 的子进程模式一致。</li></ul><p>缺点：</p><ul><li>需要 Rust/Cargo/OpenSSL 编译环境。</li><li>要从 <code>moonlight-web-stream</code> / <code>moonlight-common</code> 中抽真实 pairing。</li></ul><p>当前状态：</p><ul><li>后端已经预留 driver 边界。</li><li>默认回退 Python 占位 driver。</li><li>可通过 <code>MOONLIGHT_DRIVER_BIN</code> 指向未来真实 driver。</li></ul><p>建议：</p><ul><li>不要现在强行大改。</li><li>先用 release runtime 验证体验。</li><li>如果串流体验值得深入，再单独做 Rust driver。</li></ul><h2 id="_4-近期最重要-todo" tabindex="-1">4. 近期最重要 TODO <a class="header-anchor" href="#_4-近期最重要-todo" aria-label="Permalink to &quot;4. 近期最重要 TODO&quot;">​</a></h2><h3 id="p0-先稳定当前可手测能力" tabindex="-1">P0：先稳定当前可手测能力 <a class="header-anchor" href="#p0-先稳定当前可手测能力" aria-label="Permalink to &quot;P0：先稳定当前可手测能力&quot;">​</a></h3><ol><li><p>启动前后端，手动测试：</p><ul><li>认证中心 MI 是否能出设备/能力。</li><li>ADB 设备绑定、控制台、串流、文件。</li><li>SSH/SFTP 控制台与文件入口。</li><li>Sunshine 扫描、保存、探测、打开串流页。</li></ul></li><li><p>明确哪些是“真能力”，哪些是“占位能力”：</p><ul><li>Sunshine scan/probe 是真。</li><li>Moonlight pairing 当前是占位。</li><li>Moonlight runtime 串流需要接 release runtime。</li></ul></li><li><p>修掉明显卡顿和路径 bug：</p><ul><li>ADB shell 回车缓冲问题。</li><li>ADB 文件 <code>/sdcard/</code> 路径重复。</li><li>设备详情页能力/绑定加载慢的问题，应该以后端缓存或手动刷新解决，不要用 localStorage。</li></ul></li></ol><h3 id="p1-接-moonlight-web-stream-runtime" tabindex="-1">P1：接 moonlight-web-stream runtime <a class="header-anchor" href="#p1-接-moonlight-web-stream-runtime" aria-label="Permalink to &quot;P1：接 moonlight-web-stream runtime&quot;">​</a></h3><p>目标不是 fork 它，而是把它当串流 runtime。</p><p>要做：</p><ul><li>在认证中心增加 runtime URL 配置或读取环境变量。</li><li><code>runtimeStatus()</code> 检测 <code>http://localhost:8080</code> 是否在线。</li><li>主机行按钮从“轻量配对”调整为“打开配对 / 打开 runtime”。</li><li>串流页 iframe 或新区域打开 runtime 对应页面。</li><li>不再把 Python mock pairing 展示成真实成功。</li></ul><p>参考路径：</p><ul><li><code>D:\\files\\References\\home\\moonlight-web-stream</code></li><li>重点： <ul><li><code>README.md</code></li><li><code>src/api/host.rs</code></li><li><code>src/api/stream.rs</code></li><li><code>web/api.ts</code></li></ul></li></ul><h3 id="p2-文件管理统一" tabindex="-1">P2：文件管理统一 <a class="header-anchor" href="#p2-文件管理统一" aria-label="Permalink to &quot;P2：文件管理统一&quot;">​</a></h3><p>目标：</p><ul><li>ADB / SSH-SFTP / AList / WebDAV 进入统一文件视图。</li><li>统一路径栏、文件列表、上传、下载、新建目录、删除。</li><li>先不要过度设计跨协议复制 UI，但后端接口可以继续补。</li></ul><h3 id="p3-清理大组件" tabindex="-1">P3：清理大组件 <a class="header-anchor" href="#p3-清理大组件" aria-label="Permalink to &quot;P3：清理大组件&quot;">​</a></h3><p>当前大文件很多，但不要大拆。</p><p>优先只拆近期触碰的区域：</p><ul><li><code>AuthorizationsView.vue</code></li><li><code>DeviceDetailView.vue</code></li><li><code>AdbWorkbench.vue</code></li><li><code>StorageCredentialsPanel.vue</code></li><li><code>GameStreamWorkbenchView.vue</code></li></ul><p>原则：</p><ul><li>拆组件，不发明总线。</li><li>只拆明显重复 UI 和表格/弹窗。</li><li>不碰 LLM Studio / 记忆 / studio 大画布那边。</li></ul><h2 id="_5-当前风险点" tabindex="-1">5. 当前风险点 <a class="header-anchor" href="#_5-当前风险点" aria-label="Permalink to &quot;5. 当前风险点&quot;">​</a></h2><ol><li>工作区改动较多，提交前要认真分组。</li><li><code>packages/moonlight-driver</code> 当前是 mock，不可宣传为真实 Moonlight 配对。</li><li><code>streaming-gateway.service.ts</code> 已经偏大，后续可以拆 runtime/probe/host/pairing helper，但不要大重构。</li><li>Windows 下 Rust/OpenSSL 编译会卡时间，短期不建议作为主线。</li><li>Sunshine 端口： <ul><li><code>47990</code> 多数是 HTTPS Web UI。</li><li><code>47989</code> 也可能可达，但不一定是主要 Web UI。</li></ul></li><li>Sunshine 自签证书要允许后端探测，不代表浏览器 iframe 一定能无感加载。</li></ol><h2 id="_6-推荐下一步" tabindex="-1">6. 推荐下一步 <a class="header-anchor" href="#_6-推荐下一步" aria-label="Permalink to &quot;6. 推荐下一步&quot;">​</a></h2><p>最推荐下一步：</p><ol><li>下载或运行 <code>moonlight-web-stream</code> release。</li><li>确认 <code>http://localhost:8080</code> 能打开。</li><li>在 HomeSense 里把 Sunshine/Moonlight 面板改成 runtime 入口： <ul><li>检测 runtime</li><li>打开 runtime</li><li>打开配对页</li><li>打开串流页</li></ul></li><li>暂时弱化/隐藏当前 mock pairing。</li><li>手测真实串流体验，再决定是否做内置 Rust driver。</li></ol><p>一句话结论：</p><p>近期主线不是继续扩架构，而是把“设备能力 + 文件 + 串流”稳定成可手测、可演示的系统能力。Moonlight 先接 runtime，后续再决定是否内化成 driver。</p>',76)])])}const p=i(t,[["render",r]]);export{m as __pageData,p as default};
